args<-commandArgs(TRUE);P<-normalizePath(args[1]);W<-file.path(P,'work/2026-10-26-map-reproductions');D<-file.path(P,'data/raw/map_reproductions_20261026');S<-file.path(P,'biofigure')
suppressPackageStartupMessages({library(ggplot2);library(sf);library(dplyr);library(tidyr);library(scatterpie);library(ggnewscale);library(ggspatial);library(patchwork);library(ggrepel)})
source(file.path(S,'scripts/figure_style.R'));set.seed(20261026)
wr<-function(x,p)jsonlite::write_json(x,p,auto_unbox=TRUE,pretty=TRUE,digits=NA)
write_plot<-function(mid,p,stem,data,qc,width,height){w<-file.path(W,mid);saveRDS(p,file.path(w,'plot.rds'));write.csv(data,file.path(P,'results/plot_data',paste0(stem,'.csv')),row.names=FALSE);qc$stem<-stem;qc$width_mm<-width;qc$height_mm<-height;wr(qc,file.path(w,'input-qc.json'));ggsave(file.path(w,'exploratory.png'),p,width=width,height=height,units='mm',dpi=180,bg='white',device=ragg::agg_png)}
base_theme<-theme_void(base_size=7,base_family='Arial')+theme(legend.title=element_text(size=7),legend.text=element_text(size=6.5),legend.key.height=grid::unit(3,'mm'),legend.key.width=grid::unit(3,'mm'),legend.spacing.y=grid::unit(1.5,'mm'),legend.margin=margin(1,1,1,1),plot.margin=margin(2,2,2,2),panel.border=element_rect(fill=NA,colour='#7B8185',linewidth=.25))
world<-ggplot2::map_data('world');write.csv(world,file.path(P,'results/plot_data/map_world_geometry_20261026.csv'),row.names=FALSE)
# Exact geographic anchors, deterministic synthetic ecotype counts.
world_counts<-data.frame(Origin=c('USA','Canada','UK','France','Germany','Spain','Italy','Poland','Sweden','Norway','Finland','Russia','Turkey','China','India','Japan','South Korea','Australia','New Zealand','Argentina','Brazil','Chile'),Longitude=c(-100,-105,-2,2,10,-4,12,19,16,9,26,100,35,105,79,138,128,135,173,-64,-52,-71),Latitude=c(39,56,54,47,51,40,43,52,62,62,64,62,39,35,23,37,36,-25,-41,-35,-14,-33))
n<-nrow(world_counts);world_counts$Total<-c(83,32,101,165,250,36,64,109,51,39,31,84,27,690,42,25,23,38,14,12,10,8)
fractions<-cbind(Spring=runif(n,.12,.8),`Semi-Winter`=runif(n,.05,.7),Winter=runif(n,.08,.9));fractions<-fractions/rowSums(fractions);counts<-t(vapply(seq_len(n),function(i){x<-floor(fractions[i,]*world_counts$Total[i]);x[3]<-world_counts$Total[i]-sum(x[1:2]);x},numeric(3)));colnames(counts)<-c('Spring','Semi-Winter','Winter');world_counts<-cbind(world_counts,counts);world_counts<-world_counts[order(-world_counts$Total),];world_counts$radius_deg<-log10(world_counts$Total+1)*2
stopifnot(all(rowSums(world_counts[,c('Spring','Semi-Winter','Winter')])==world_counts$Total),length(unique(world_counts$Origin))==n)
world_joined<-left_join(world,world_counts[,c('Origin','Total')],by=c('region'='Origin'));stopifnot(nrow(world_joined)==nrow(world));eco<-bf_palette('tol-bright-7',kind='categorical',n=7,skill_root=S)[c(4,5,1)];names(eco)<-c('Spring','Semi-Winter','Winter')
p<-ggplot()+geom_polygon(data=world_joined,aes(long,lat,group=group,fill=Total),colour='#6E767C',linewidth=.1)+bf_scale_fill('sequential','biofigure-light-aqua-blue',limits=c(0,700),name='Accessions',breaks=c(0,100,300,700),na.value='white',skill_root=S)+new_scale_fill()+geom_scatterpie(data=head(world_counts,20),aes(Longitude,Latitude,r=radius_deg),cols=c('Spring','Semi-Winter','Winter'),colour='#20272D',linewidth=.16)+scale_fill_manual(values=eco,name='Ecotype')+geom_scatterpie_legend(r=log10(c(10,100,1000)+1)*2,x=-132,y=-30,n=3,breaks=log10(c(10,100,1000)+1)*2,labeller=function(r)format(round(10^(r/2)-1),trim=TRUE),size=2.4,family='Arial')+annotate('text',x=-126,y=-13,label='Accessions',size=2.5,family='Arial')+coord_quickmap(xlim=c(-180,180),ylim=c(-57,84),expand=FALSE)+base_theme+theme(legend.position='right')
write_plot('SCICASE-090',p,'world_ecotype_map_20261026',world_counts,list(data_origin='User-authorized deterministic synthetic accessions; no observed accessions or ecotype evidence.',seed=20261026,crs='EPSG:4326; coord_quickmap equirectangular aspect approximation',countries=n,pies=20,total_accessions=sum(world_counts$Total),count_closure=TRUE,join_preserves_geometry_rows=TRUE,size_mapping='radius in geographic degrees =2*log10(Total+1); legend uses exact inverse'),183,88)
# Real province geometry and real city coordinates; all depletion values synthetic.
china<-st_read(file.path(D,'china-provinces.geojson'),quiet=TRUE);china<-st_make_valid(china);china<-st_transform(china,4326);code<-suppressWarnings(as.integer(china$adcode))
eng<-c('Beijing','Tianjin','Hebei','Shanxi','Inner Mongolia','Liaoning','Jilin','Heilongjiang','Shanghai','Jiangsu','Zhejiang','Anhui','Fujian','Jiangxi','Shandong','Henan','Hubei','Hunan','Guangdong','Guangxi','Hainan','Chongqing','Sichuan','Guizhou','Yunnan','Tibet','Shaanxi','Gansu','Qinghai','Ningxia','Xinjiang','Taiwan','Hong Kong','Macao','')
china$Province<-eng;aeqd<-'+proj=aeqd +lat_0=35 +lon_0=105 +datum=WGS84 +units=m +no_defs';projected<-st_transform(china,aeqd)
centers<-suppressWarnings(st_point_on_surface(projected));cc<-as.data.frame(st_coordinates(centers));cc$Province<-china$Province;cc$adcode<-code;cc<-cc[cc$Province!='',]
# Avoid a dense small-city label cluster; city bubbles still retain every site.
cc<-cc[!cc$Province%in%c('Hong Kong','Macao','Beijing','Tianjin','Shanghai'),]
data(world.cities,package='maps');city_candidates<-subset(world.cities,country.etc=='China' & pop>70000)
pts<-st_as_sf(city_candidates,coords=c('long','lat'),crs=4326,remove=FALSE);inside<-lengths(st_intersects(st_transform(pts,aeqd),st_make_valid(projected[projected$Province!='',])))>0;city_candidates<-city_candidates[inside,];city_candidates<-city_candidates[sample(nrow(city_candidates),155),];city_candidates$Value<-round(exp(runif(nrow(city_candidates),log(8),log(640))),1);city_candidates$Level<-cut(city_candidates$Value,breaks=c(0,50,100,300,650),labels=c('< 50','50 - 100','100 - 300','300 - 650'),right=FALSE)
pts<-st_transform(st_as_sf(city_candidates,coords=c('long','lat'),crs=4326,remove=FALSE),aeqd);xy<-st_coordinates(pts);city_candidates$X<-xy[,1];city_candidates$Y<-xy[,2]
write.csv(cc,file.path(P,'results/plot_data/china_map_labels_20261026.csv'),row.names=FALSE)
# Illustrative synthetic divider, explicitly not a recovered Qinling-Huaihe boundary.
line_coords<-matrix(c(78,32,84,32.6,89,33,94,33.2,99,32.4,103,32,106,32.6,109,33.4,112,33.1,115,33.2,118,33.3,120.5,33.7),ncol=2,byrow=TRUE);divider<-st_sf(type='Illustrative division line',geometry=st_sfc(st_linestring(line_coords),crs=4326));write.csv(data.frame(longitude=line_coords[,1],latitude=line_coords[,2]),file.path(P,'results/plot_data/china_map_illustrative_divider_20261026.csv'),row.names=FALSE)
colors<-bf_palette('tol-bright-7',kind='categorical',n=3,skill_root=S);red<-colors[2];green<-colors[3]
p<-ggplot()+geom_sf(data=projected,fill='white',colour='#929B9F',linewidth=.19)+geom_sf(data=st_transform(divider,aeqd),aes(colour=type),linewidth=.65)+geom_point(data=city_candidates,aes(X,Y,size=Level),shape=21,fill='#EFA5A3',colour='#B94949',stroke=.2,alpha=.85)+scale_size_manual(values=c(1.3,2.0,2.9,4.0),name='City-level groundwater depletion\n(million m³)')+scale_colour_manual(values=c('Illustrative division line'=green),name=NULL)+geom_text_repel(data=cc,aes(X,Y,label=Province),size=2.3,family='Arial',colour='#303840',min.segment.length=1,segment.size=.15,segment.colour='#80888D',box.padding=.16,point.padding=.1,max.overlaps=Inf,seed=20261026)+coord_sf(crs=aeqd,xlim=c(-2.7e6,2.5e6),ylim=c(-2.15e6,2.45e6),expand=FALSE)+annotation_scale(location='bl',width_hint=.18,text_cex=.78,height=grid::unit(1.3,'mm'))+annotation_north_arrow(location='tr',height=grid::unit(7,'mm'),width=grid::unit(7,'mm'),style=north_arrow_fancy_orienteering(text_size=6.5))+base_theme+theme(legend.position='right',panel.border=element_blank())
inset<-ggplot()+geom_sf(data=china,fill='white',colour='#969FA3',linewidth=.14)+coord_sf(xlim=c(105,125),ylim=c(3,24),expand=FALSE)+theme_void()+theme(panel.border=element_rect(fill=NA,colour='#6F787E',linewidth=.25),plot.margin=margin(0,0,0,0))
p<-p+inset_element(inset,left=.81,bottom=.015,right=.99,top=.24,align_to='panel')
write_plot('SCICASE-092',p,'china_groundwater_map_20261026',city_candidates,list(data_origin='User-authorized synthetic groundwater values and illustrative division line; actual city coordinates from maps::world.cities and actual province boundaries.',seed=20261026,crs=aeqd,cities=nrow(city_candidates),city_coordinates_real=TRUE,all_selected_points_intersect_real_province_geometry=TRUE,provinces=sum(china$Province!=''),levels=as.list(table(city_candidates$Level)),divider_is_synthetic=TRUE,original_data2_xlsx='NOT_AVAILABLE',original_north_south_line='NOT_AVAILABLE; do not interpret this demonstration line as the actual boundary.'),183,143)
# Source code explicitly creates random groups: seeded tutorial replay, no study inference.
source_code<-file.path(P,'biofigure/library/topjournal-corpus/results/code/issue_012/block_001.R');code_lines<-readLines(source_code);start<-grep('^cities <- tibble',code_lines);set.seed(20261026);eval(parse(text=paste(code_lines[start:length(code_lines)],collapse='\n')))
stopifnot(nrow(cities)==65,nrow(df_st_as_sf)==65,all(cities$latitude>=-90&cities$latitude<=90),all(cities$longitude>=-180&cities$longitude<=180))
# Fourth category is a filled ring in the tutorial, not the paper's independent sampling flag.
cols<-bf_palette('tol-bright-7',kind='categorical',n=4,skill_root=S);cols<-c('#969A9A',cols[2],cols[3],cols[4]);names(cols)<-levels(cities$group)
make_map<-function(file){r<-terra::rast(file);r<-terra::aggregate(r,fact=3);rgb<-terra::as.data.frame(r,xy=TRUE);names(rgb)<-c('x','y','red','green','blue');rgb$hex<-rgb(pmax(0,pmin(255,rgb$red)),pmax(0,pmin(255,rgb$green)),pmax(0,pmin(255,rgb$blue)),maxColorValue=255);rgb<-rgb[,c('x','y','hex')];ggplot()+geom_raster(data=rgb,aes(x,y,fill=hex),interpolate=TRUE)+scale_fill_identity()+new_scale_fill()+geom_point(data=cities,aes(longitude,latitude,fill=group),shape=21,size=1.9,stroke=.28,colour='#26313A')+scale_fill_manual(values=cols,name=NULL,drop=FALSE)+coord_quickmap(xlim=c(-180,180),ylim=c(-58,84),expand=FALSE)+base_theme+theme(legend.position='bottom',legend.direction='horizontal',legend.box='vertical')+guides(fill=guide_legend(nrow=2,byrow=TRUE,override.aes=list(size=2.1)))}
p1<-make_map(file.path(D,'NE2_50M_SR/NE2_50M_SR.tif'));p2<-make_map(file.path(D,'NE1_50M_SR_W/NE1_50M_SR_W.tif'));p<-(p1/p2)+plot_layout(heights=c(1,1))
write_plot('REPRO-012',p,'sampling_relief_maps_20261026',as.data.frame(cities),list(data_origin='65 coordinates exactly transcribed in archived tutorial code; source-generated random category assignment with fixed seed, not study observations.',seed=20261026,crs='EPSG:4326; coord_quickmap',sites=65,categories=as.list(table(cities$group)),panels=2,terrain='Exact Natural Earth NE2_50M_SR and NE1_50M_SR_W raster products; three-fold aggregation for final physical size.',original_science_study_data='Not used; tutorial replay only',limitations='Source tutorial does not provide its original random seed; current category memberships are a deterministic new realization. Two raster treatments share the same65 locations and memberships.'),183,183)
